    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.u32 %r4, %r1, %r2, %r3;
    mov.u32 %r11, %r4;
    mov.u32 %r5, %nctaid.x;
    mul.lo.u32 %r10, %r5, %r2;
    shl.b32 %r14, %r10, 2;
