    @%p1 bra TAIL;
    add.u32 %r13, %r4, %r10;
    add.u32 %r15, %r13, %r10;
    add.u32 %r16, %r15, %r10;
    setp.ge.u32 %p3, %r13, %r7;
    setp.ge.u32 %p4, %r15, %r7;
    setp.ge.u32 %p5, %r16, %r7;
    mul.wide.u32 %rd3, %r4, 16;
    add.s64 %rd4, %rd1, %rd3;
    add.s64 %rd5, %rd2, %rd3;
    mul.wide.u32 %rd8, %r13, 16;
    add.s64 %rd9, %rd1, %rd8;
    add.s64 %rd10, %rd2, %rd8;
    mul.wide.u32 %rd13, %r15, 16;
    add.s64 %rd14, %rd1, %rd13;
    add.s64 %rd15, %rd2, %rd13;
    mul.wide.u32 %rd16, %r16, 16;
