    tanh.approx.f32 %f1, %f1;
    tanh.approx.f32 %f2, %f2;
    tanh.approx.f32 %f3, %f3;
    tanh.approx.f32 %f4, %f4;
    @!%p3 tanh.approx.f32 %f5, %f5;
    @!%p3 tanh.approx.f32 %f6, %f6;
    @!%p3 tanh.approx.f32 %f7, %f7;
    @!%p3 tanh.approx.f32 %f8, %f8;
    @!%p4 tanh.approx.f32 %f9, %f9;
    @!%p4 tanh.approx.f32 %f10, %f10;
    @!%p4 tanh.approx.f32 %f11, %f11;
    @!%p4 tanh.approx.f32 %f12, %f12;
    @!%p5 tanh.approx.f32 %f13, %f13;
    @!%p5 tanh.approx.f32 %f14, %f14;
    @!%p5 tanh.approx.f32 %f15, %f15;
    @!%p5 tanh.approx.f32 %f16, %f16;
