    @!%p3 st.global.v4.f32 [%rd10], {%f5, %f6, %f7, %f8};
    @!%p4 st.global.v4.f32 [%rd15], {%f9, %f10, %f11, %f12};
    @!%p5 st.global.v4.f32 [%rd18], {%f13, %f14, %f15, %f16};
    add.u32 %r4, %r4, %r14;
    bra VEC_LOOP;
TAIL:
    shl.b32 %r9, %r7, 2;
    setp.ge.u32 %p2, %r11, %r8;
    @%p2 bra DONE;
