    mul.wide.u32 %rd6, %r12, 4;
    add.s64 %rd7, %rd1, %rd6;
    add.s64 %rd11, %rd2, %rd6;
    ld.global.nc.f32 %f17, [%rd7];
    tanh.approx.f32 %f18, %f17;
    st.global.f32 [%rd11], %f18;
